#!/usr/bin/env python3
"""Build every generated file of this extension from the pinned facts.

Inputs: tests/reference/jotform_api.json (extract_reference.py, from the pinned
request-models.js), names.py (titles, areas and the operations that are not steps),
step_ids.json (frozen step ids) and composite_specs.py (the everyday steps). Outputs:
runtime/registry.json, the four contract files, ui/actions/actions.yaml, the API and
Coverage pages, and extension.yaml. Run from the bundle root:

    python3 tests/reference/build_contracts.py

tests/test_contracts.py fails when a committed file differs from what this script
renders, so the files never drift from the documentation.

A step id is written once to step_ids.json (``--new-ids`` adds ids for operations
that have none) and never derived again: titles may change, ids may not.
"""

from __future__ import annotations

import html
import json
import re
import sys
from pathlib import Path
from typing import Any

import yaml

HERE = Path(__file__).resolve().parent
BUNDLE = HERE.parents[1]
sys.path.insert(0, str(HERE))
sys.path.insert(0, str(BUNDLE))

import composite_specs  # noqa: E402
import names  # noqa: E402

from runtime import identity  # noqa: E402

FACTS = HERE / "jotform_api.json"
STEP_IDS = HERE / "step_ids.json"
CONNECTION_TYPE = "jotform"
HEADER = (
    "# Generated by tests/reference/build_contracts.py from the pinned specification facts.\n"
    "# Do not edit by hand: tests/test_contracts.py fails when this file drifts.\n"
)
RESERVED_INPUTS = frozenset({"connection_ref"})
MAX_DOWNLOAD_BYTES = 40 * 1024 * 1024
MAX_REPORT_BYTES = 2 * 1024 * 1024
DOWNLOAD_BINDING = "jotform_file"
UPLOAD_BINDING = "jotform_upload"
REPORT_BINDING = "jotform_report"
ERROR_CODES_READ = [
    "invalid_payload",
    "invalid_host_envelope",
    "invalid_connection",
    "setup_required",
    "unsupported_operation",
    "internal_error",
    "authentication_failed",
    "not_found",
    "conflict",
    "upstream_validation_failed",
    "upstream_failure",
    "rate_limited",
    "invalid_response",
    "response_too_large",
    "timeout",
    "connection_failed",
    "redirect_rejected",
    "blocked_address",
    "artifact_output_unavailable",
]
ERROR_CODES_WRITE = ERROR_CODES_READ + ["timeout_unknown"]
WARNINGS_OUTPUT = composite_specs.WARNINGS
PROCESSING_OUTPUTS = composite_specs.PROCESSING_OUTPUTS

#: The success status of every operation: the documentation's answers are HTTP 200 with
#: ``"responseCode": 200`` and ``"message": "success"`` (every response sample of the
#: page), and its client counts an answer as successful only on ``responseCode`` 200.
SUCCESS = ["200"]

#: Operations that are not GET but change nothing: none. Every POST, PUT and DELETE of
#: the pinned list creates, adds, edits, updates, clones, removes or deletes something
#: (its definition and explanation say so); the one POST that only answers (POST
#: /user/login, signing in) is not a step. An entry needs the documentation's own words
#: that the operation only reads; on any doubt it stays a change.
READ_ONLY_NON_GET: dict[tuple[str, str], str] = {}
#: GET operations that change something: none among the steps. GET /user/logout ends a
#: session and is not a step (names.EXCLUDED).
WRITING_GET: dict[tuple[str, str], str] = {}

#: Writes the documentation says are carried out afterwards: none. No answer of the
#: pinned list is HTTP 202 or described as asynchronous; every response sample returns
#: the changed record or confirms the change.
ACCEPTED_ONLY: dict[tuple[str, str], tuple[tuple[str, str] | None, str]] = {}

#: The top level of a JSON body, from the documentation's curl examples: a list for the
#: submissions (``-d '[{"1":{"text":…}}, …]'``), an object everywhere else.
JSON_BODY_TYPES: dict[tuple[str, str], str] = {("PUT", "/form/{id}/submissions"): "array"}
#: Writes whose answer is a list of the records sent (class b of table T).
BATCH_WRITES = frozenset({("PUT", "/form/{id}/submissions")})

REGION_HOSTS = ["api.jotform.com", "eu-api.jotform.com", "hipaa-api.jotform.com"]
#: The address of uploaded files (the form uploads documentation): www.jotform.com/uploads.
UPLOAD_HOSTS = ["*.jotform.com"]


# -- names ---------------------------------------------------------------------------------


def snake(text: str) -> str:
    text = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", text)
    text = re.sub(r"[^A-Za-z0-9]+", "_", text)
    return text.strip("_").lower()


def key(op: dict[str, Any]) -> str:
    return f"{op['method']} {op['path']}"


def facts() -> dict[str, Any]:
    return json.loads(FACTS.read_text(encoding="utf-8"))


def step_ids() -> dict[str, str]:
    return json.loads(STEP_IDS.read_text(encoding="utf-8")) if STEP_IDS.exists() else {}


def new_step_id(title: str) -> str:
    words = [w for w in snake(title).split("_") if w not in {"a", "an", "the"}]
    return "_".join(words)


def operations(data: dict[str, Any]) -> list[dict[str, Any]]:
    """The documented operations that are steps (all but the excluded ones)."""
    return [op for op in data["operations"] if (op["method"], op["path"]) not in names.EXCLUDED]


# -- text ----------------------------------------------------------------------------------


def clean(text: str) -> str:
    text = re.sub(r"<br\s*/?>", " ", text or "", flags=re.IGNORECASE)
    text = re.sub(r"<[^>]+>", "", text)
    text = html.unescape(text)
    text = " ".join(text.split())
    text = re.sub(r"\blimits\b", "maximums", text)
    return re.sub(r"\(IMPORTANT: This endpoint is deprecated\.[^)]*\)", "", text).strip()


def sentences(text: str, limit: int) -> str:
    text = clean(text)
    out = ""
    for part in re.split(r"(?<=[.!?])\s+", text):
        if not part:
            continue
        candidate = f"{out} {part}".strip()
        if len(candidate) > limit:
            break
        out = candidate
    if not out and text:
        out = text[: limit - 1].rstrip() + "…"
    return out


# -- parameters ----------------------------------------------------------------------------


def _maximum(description: str) -> int | None:
    match = re.search(r"Maximum is (\d+)", description)
    return int(match.group(1)) if match else None


def query_node(prm: dict[str, Any]) -> dict[str, Any]:
    """How one query parameter is checked and sent (see runtime/params.py)."""
    kind = prm["type"]
    out: dict[str, Any] = {"required": prm["required"]}
    if kind == "Number":
        out["kind"] = "integer"
        if prm["name"] == "limit":
            out["minimum"] = 1
            out["maximum"] = _maximum(prm["description"]) or 1000
        else:
            out["minimum"] = 0
            out["maximum"] = 10_000_000
    elif kind == "jsonString":
        out["kind"] = "json_text"
    elif kind == "Enum":
        out["kind"] = "text"
        out["max_length"] = 100
        out["allowed"] = [str(v) for v in prm["values"]]
    elif "MM/DD/YYYY" in prm["description"]:
        out["kind"] = "date_mdy"
    elif kind == "String":
        out["kind"] = "text"
        out["max_length"] = 2000
    else:
        raise SystemExit(f"query parameter {prm['name']} of type {kind!r} is not handled")
    return out


def form_node(prm: dict[str, Any]) -> dict[str, Any]:
    out: dict[str, Any] = {"required": prm["required"]}
    if prm["type"] == "JSON":
        out["kind"] = "json_text"
    else:
        out["kind"] = "text"
        out["max_length"] = 10000
        if prm.get("values"):
            out["allowed"] = [str(v) for v in prm["values"]]
    return out


def path_node(prm: dict[str, Any]) -> dict[str, Any]:
    out: dict[str, Any] = {"required": True, "kind": "text", "max_length": 200}
    if prm.get("values"):
        out["allowed"] = [str(v) for v in prm["values"]]
    return out


def input_name(param: str) -> str:
    return snake(param.replace("[]", ""))


def kind_of(op: dict[str, Any]) -> str:
    where = (op["method"], op["path"])
    if where in WRITING_GET:
        return "write"
    if op["method"] == "GET" or where in READ_ONLY_NON_GET:
        return "read"
    return "write"


def documented_refusals(op: dict[str, Any]) -> dict[str, bool]:
    """Statuses the operation documents as refusals (``statusCodes``): {status: its body
    must have the answer form}."""
    return {str(s["code"]): True for s in op["status_codes"] if 400 <= s["code"] < 500}


def describe(op: dict[str, Any], entry: dict[str, Any]) -> str:
    text = sentences(op["explanation"], 420) or (op["definition"] or entry["title"]).rstrip(".")
    if not text.endswith((".", "!", "?", "…")):
        text += "."
    notes: list[str] = []
    if entry["deprecated"]:
        notes.append("Jotform marks this operation as deprecated in favour of the labels.")
    if entry["json_body"]:
        shape = "list" if entry["json_body"]["type"] == "array" else "object"
        notes.append(f"{entry['json_body']['input']} is the JSON {shape} the documentation shows.")
    for group in entry["groups"]:
        notes.append(
            f"{group['input']} is an object: each key becomes the form field "
            f"{group['prefix']}[key] (nested objects {group['prefix']}[key][part])."
        )
    if entry["paged"]:
        notes.append("Pages with offset and limit; result_set says what the page holds.")
    return " ".join([text, *notes])


def registry_entry(op: dict[str, Any], ids: dict[str, str]) -> dict[str, Any]:
    path_params: list[dict[str, Any]] = []
    query: list[dict[str, Any]] = []
    form: list[dict[str, Any]] = []
    groups: dict[str, dict[str, Any]] = {}
    json_body: dict[str, Any] | None = None
    for prm in op["parameters"]:
        where = prm["parameter_type"]
        if prm["name"] == "apikey":
            # The connection's API key, sent in the APIKEY header.
            continue
        if where == "url":
            token = (prm["replace"] or "").strip("{}")
            if "{" + token + "}" not in op["path"]:
                raise SystemExit(f"{key(op)}: {prm['name']} replaces {token}, not in the path")
            path_params.append(
                {
                    "name": prm["name"],
                    "token": token,
                    "input": input_name(prm["name"]),
                    "node": path_node(prm),
                    "description": clean(prm["description"]),
                }
            )
        elif where == "query":
            query.append(
                {
                    "name": prm["name"],
                    "input": input_name(prm["name"]),
                    "node": query_node(prm),
                    "description": clean(prm["description"]),
                    "values": prm["values"],
                }
            )
        elif where == "post" and "[" in prm["name"]:
            prefix = prm["name"].split("[", 1)[0]
            group = groups.setdefault(
                prefix,
                {"prefix": prefix, "input": input_name(prefix), "required": False, "members": []},
            )
            group["required"] = group["required"] or prm["required"]
            group["members"].append(
                {
                    "name": prm["name"],
                    "description": clean(prm["description"]),
                    "values": prm["values"],
                }
            )
        elif where == "post":
            form.append(
                {
                    "name": prm["name"],
                    "input": input_name(prm["name"]),
                    "node": form_node(prm),
                    "description": clean(prm["description"]),
                }
            )
        elif where == "JSON":
            if json_body is not None:
                raise SystemExit(f"{key(op)}: two JSON bodies")
            json_body = {
                "name": prm["name"],
                "input": input_name(prm["name"]),
                "required": prm["required"],
                "type": JSON_BODY_TYPES.get((op["method"], op["path"]), "object"),
                "description": clean(prm["description"]),
            }
        else:
            raise SystemExit(f"{key(op)}: parameter kind {where!r} is not handled")
    tokens = set(re.findall(r"\{([^}]+)\}", op["path"]))
    if tokens != {p["token"] for p in path_params}:
        raise SystemExit(f"{key(op)}: path tokens {tokens} documented as {path_params}")
    where_key = (op["method"], op["path"])
    query_names = {p["name"] for p in query}
    entry: dict[str, Any] = {
        "title": names.TITLES[where_key],
        "method": op["method"],
        "path": op["path"],
        "doc_id": op["doc_id"],
        "definition": op["definition"],
        "area": names.area_of(op["path"]),
        "kind": kind_of(op),
        "deprecated": "deprecated" in op["explanation"].lower(),
        "path_params": path_params,
        "query": query,
        "form": form,
        "groups": list(groups.values()),
        "json_body": json_body,
        "paged": {"offset", "limit"} <= query_names,
        "success": SUCCESS,
        "refusals": documented_refusals(op),
    }
    if entry["kind"] == "write":
        entry["step_class"] = "confirm_batch" if where_key in BATCH_WRITES else "confirm"
        always = where_key in ACCEPTED_ONLY
        check = ACCEPTED_ONLY[where_key][0] if always else None
        entry["processing"] = {
            "accepted_always": always,
            "check": ids[f"{check[0]} {check[1]}"] if check else None,
        }
    entry["description"] = describe(op, entry)
    used = (
        [p["input"] for p in path_params + query + form]
        + [g["input"] for g in groups.values()]
        + ([json_body["input"]] if json_body else [])
    )
    if len(set(used)) != len(used) or set(used) & RESERVED_INPUTS:
        raise SystemExit(f"{key(op)}: input names collide: {used}")
    return entry


def ordered_operations(
    data: dict[str, Any], ids: dict[str, str]
) -> list[tuple[str, dict[str, Any]]]:
    """Areas in order, then the order of the titles; deletions last in each area."""
    area_order = list(names.AREAS)
    title_order = list(names.TITLES)
    rows = []
    for op in operations(data):
        area = names.area_of(op["path"])
        rows.append(
            (
                area_order.index(area),
                op["method"] == "DELETE",
                title_order.index((op["method"], op["path"])),
                ids[key(op)],
                op,
            )
        )
    rows.sort(key=lambda r: r[:3])
    return [(r[3], r[4]) for r in rows]


def build_registry(data: dict[str, Any], ids: dict[str, str]) -> dict[str, Any]:
    ops = {sid: registry_entry(op, ids) for sid, op in ordered_operations(data, ids)}
    return {"source": data["source"], "operations": ops}


# -- contract rows -------------------------------------------------------------------------


def value_type(schema: dict[str, Any]) -> str:
    kind = schema.get("type")
    if isinstance(kind, list):
        kinds = [k for k in kind if k != "null"]
        if "string" in kinds or not kinds:
            return "text"
        kind = kinds[0]
    return {"integer": "integer", "boolean": "boolean", "array": "array", "object": "object"}.get(
        str(kind), "text"
    )


def node_schema(n: dict[str, Any], *, title: str, description: str) -> dict[str, Any]:
    kind = n["kind"]
    schema: dict[str, Any]
    if kind == "integer":
        schema = {"type": "integer", **{k: n[k] for k in ("minimum", "maximum") if k in n}}
    elif kind == "json_text":
        schema = {"type": "object", "additionalProperties": True}
    elif kind == "date_mdy":
        schema = {"type": "string", "maxLength": 10}
    else:
        schema = {"type": "string", "maxLength": n["max_length"]}
        if n.get("allowed"):
            schema["enum"] = n["allowed"]
    schema["title"] = title
    if description:
        schema["description"] = description
    return schema


def widget_for(n: dict[str, Any]) -> str:
    kind = n["kind"]
    if kind == "integer":
        return "integer"
    if kind == "json_text":
        return "json"
    if n.get("allowed"):
        return "select"
    return "text"


def step_inputs(entry: dict[str, Any]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for prm in entry["path_params"]:
        rows.append(
            {
                "name": prm["input"],
                "required": True,
                "schema": node_schema(
                    prm["node"],
                    title=prm["name"],
                    description=(prm["description"] or f"The {prm['name']} in the path.")[:400],
                ),
                "widget": widget_for(prm["node"]),
                "options": prm["node"].get("allowed"),
            }
        )
    for prm in entry["query"] + entry["form"]:
        n = prm["node"]
        description = prm["description"] or prm["name"]
        if n["kind"] == "json_text" and prm.get("values"):
            description += " Fields: " + ", ".join(prm["values"]) + " (with :gt, :lt or :ne)."
        rows.append(
            {
                "name": prm["input"],
                "required": bool(n["required"]),
                "schema": node_schema(n, title=prm["name"], description=description[:400]),
                "widget": widget_for(n),
                "options": n.get("allowed"),
            }
        )
    for group in entry["groups"]:
        documented = ", ".join(m["name"] for m in group["members"])
        rows.append(
            {
                "name": group["input"],
                "required": group["required"],
                "schema": {
                    "type": "object",
                    "additionalProperties": True,
                    "title": group["prefix"],
                    "description": (
                        f"Form fields {group['prefix']}[…] as an object: each key becomes "
                        f"{group['prefix']}[key], nested objects {group['prefix']}[key][part]. "
                        f"Documented: {documented}."
                    )[:400],
                },
                "widget": "json",
            }
        )
    body = entry["json_body"]
    if body:
        rows.append(
            {
                "name": body["input"],
                "required": body["required"],
                "schema": {
                    "type": body["type"],
                    **({"additionalProperties": True} if body["type"] == "object" else {}),
                    "title": body["name"],
                    "description": (
                        (body["description"] or body["name"])
                        + " Sent as the JSON body, as the documentation shows it."
                    )[:400],
                },
                "widget": "json",
            }
        )
    return rows


RESULT_SET_OUTPUT = {
    "name": "result_set",
    "type": ["object", "null"],
    "additionalProperties": True,
    "description": "What the page holds: offset, limit, count (and orderby, filter).",
}


def generic_outputs(entry: dict[str, Any]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = [
        {
            "name": "status",
            "type": ["integer", "null"],
            "description": "The HTTP status (none in a test run).",
        },
        {
            "name": "data",
            "type": ["object", "array", "string", "number", "boolean", "null"],
            "description": "What Jotform returned as content (JSON).",
        },
    ]
    if entry["paged"]:
        rows.append(RESULT_SET_OUTPUT)
    rows.append(composite_specs.LIMIT_LEFT)
    if entry["kind"] == "write":
        rows += PROCESSING_OUTPUTS
    if entry.get("step_class") == "confirm_batch":
        rows.append(composite_specs.UNANSWERED_OUTPUT)
    rows.append(WARNINGS_OUTPUT)
    if entry["kind"] == "write":
        rows += [
            {"name": "external_effect_status", "type": "string"},
            {"name": "definitely_no_external_effect", "type": "boolean"},
        ]
    return rows


def output_row(row: dict[str, Any]) -> dict[str, Any]:
    schema = {k: v for k, v in row.items() if k not in {"name", "value_type"}}
    vt = row.get("value_type") or value_type(schema)
    if row["name"] == "data":
        vt = "object"
        schema["additionalProperties"] = True
    return {"name": row["name"], "value_type": vt, "schema": schema}


def composite_input_rows(spec: dict[str, Any]) -> list[dict[str, Any]]:
    required_names = composite_specs.REQUIRED.get(spec["operation_id"], frozenset())
    rows = []
    for item in spec["inputs"]:
        schema = {k: v for k, v in item.items() if k != "name"}
        kind = item["type"]
        widget = "text"
        if kind == "integer":
            widget = "integer"
        elif kind == "boolean":
            widget = "boolean"
        elif kind in ("array", "object") or isinstance(kind, list):
            widget = "json"
        elif item.get("enum"):
            widget = "select"
        if item["name"] == "failed_error":
            widget = "textarea"
        rows.append(
            {
                "name": item["name"],
                "required": item["name"] in required_names,
                "schema": schema,
                "widget": widget,
                "options": item.get("enum"),
            }
        )
    return rows


def everyday_outputs(spec: dict[str, Any]) -> list[dict[str, Any]]:
    rows = list(spec["outputs"])
    if spec["kind"] == "write":
        rows[-1:-1] = PROCESSING_OUTPUTS
        rows += [
            {"name": "external_effect_status", "type": "string"},
            {"name": "definitely_no_external_effect", "type": "boolean"},
        ]
    return rows


def manifest_rows(registry: dict[str, Any]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for spec in composite_specs.COMPOSITES:
        oid = spec["operation_id"]
        file_spec = composite_specs.FILES.get(oid)
        if oid == "build_support_report":
            file_spec = {**composite_specs.REPORT_FILE, "binding": REPORT_BINDING}
        rows.append(
            {
                "id": oid,
                "title": spec["title"],
                "description": spec["description"],
                "kind": spec["kind"],
                "inputs": composite_input_rows(spec),
                "outputs": everyday_outputs(spec),
                "area": "Everyday",
                "calls": spec["calls"],
                "file": file_spec,
            }
        )
    for sid, entry in registry["operations"].items():
        rows.append(
            {
                "id": sid,
                "title": entry["title"],
                "description": entry["description"],
                "kind": entry["kind"],
                "inputs": step_inputs(entry),
                "outputs": generic_outputs(entry),
                "area": entry["area"],
                "calls": [f"{entry['method']} {entry['path']}"],
                "file": None,
            }
        )
    return rows


def operation_manifest(rows: list[dict[str, Any]]) -> dict[str, Any]:
    ops = []
    for row in rows:
        write = row["kind"] == "write"
        inputs = [{"name": "connection_ref", "value_type": "connection_ref", "required": True}]
        for item in row["inputs"]:
            inputs.append(
                {
                    "name": item["name"],
                    "value_type": value_type(item["schema"]),
                    "required": item["required"],
                    "schema": item["schema"],
                }
            )
        op: dict[str, Any] = {
            "operation_id": row["id"],
            "display_name": row["title"],
            "description": row["description"],
            "operation_kind": "action" if write else "source",
            "category": "productivity",
            "connection_type_ids": [CONNECTION_TYPE],
            "workflow_visible": True,
        }
        if write:
            op["effect_kind"] = f"jotform_{row['id']}"
        outputs = [output_row(o) for o in row["outputs"]]
        op.update(
            {
                "inputs": inputs,
                "outputs": outputs,
                "result_fields": [f"result.{o['name']}" for o in outputs],
                "error_codes": ERROR_CODES_WRITE if write else ERROR_CODES_READ,
            }
        )
        ops.append(op)
    return {"operations": ops}


def step_ui_manifest(rows: list[dict[str, Any]]) -> dict[str, Any]:
    forms = []
    for row in rows:
        fields = []
        for item in row["inputs"]:
            field: dict[str, Any] = {
                "name": item["name"],
                "label": item["schema"].get("title") or item["name"],
                "widget_type": item["widget"],
                "required": item["required"],
                "help_text": (item["schema"].get("description") or item["name"])[:400],
            }
            if item.get("options"):
                field["options"] = [{"label": v, "value": v} for v in item["options"]]
            if item["widget"] == "json":
                field["placeholder"] = "[]" if item["schema"].get("type") == "array" else "{}"
            fields.append(field)
        forms.append({"operation_id": row["id"], "title": row["title"], "fields": fields})
    return {"forms": forms}


def actions_manifest(rows: list[dict[str, Any]]) -> dict[str, Any]:
    actions = []
    for row in rows:
        write = row["kind"] == "write"
        action: dict[str, Any] = {
            "action_id": row["id"],
            "title": row["title"],
            "description": row["description"],
            "required_scopes": ["extension:invoke"],
            "handler": {"mode": "extension"},
        }
        if write:
            action["command_type"] = "invoke_extension_action"
        action.update(
            {
                "mutates_platform": write,
                "workflow_visible": True,
                "parameters": [
                    {"name": "connection_ref", "type": "connection_ref", "required": True}
                ]
                + [
                    {
                        "name": i["name"],
                        "type": value_type(i["schema"])
                        if value_type(i["schema"]) != "text"
                        else "string",
                        "required": i["required"],
                    }
                    for i in row["inputs"]
                ],
                "result_fields": [o["name"] for o in row["outputs"]],
                "error_codes": ERROR_CODES_WRITE if write else ERROR_CODES_READ,
            }
        )
        actions.append(action)
    return {"actions": actions}


def artifact_policies(rows: list[dict[str, Any]]) -> dict[str, Any]:
    policies = []
    for row in rows:
        spec = row.get("file")
        if not spec:
            continue
        binding = spec.get("binding") or DOWNLOAD_BINDING
        policies.append(
            {
                "operation_id": row["id"],
                "outputs": [
                    {
                        "kind": "artifact",
                        "value_type": "artifact_handle",
                        "binding_key": binding,
                        "filename": spec["filename"],
                        "content_type": spec["content_type"],
                        "max_size_bytes": MAX_REPORT_BYTES
                        if binding == REPORT_BINDING
                        else MAX_DOWNLOAD_BYTES,
                        "retention_class": "run_window",
                    }
                ],
            }
        )
    return {"artifact_policies": policies}


