# -- UI pages ------------------------------------------------------------------------------

PAGE_IDS = {
    "Forms and questions": "jotform-api-forms",
    "Submissions and webhooks": "jotform-api-submissions",
    "Reports, labels and folders": "jotform-api-reports",
    "Account": "jotform-api-account",
}


def step_text(row: dict[str, Any]) -> str:
    kind = "changes data in Jotform" if row["kind"] == "write" else "reads only"
    calls = ", ".join(f"`{c}`" for c in row["calls"])
    inputs = [f"`{i['name']}`" + (" (required)" if i["required"] else "") for i in row["inputs"]]
    lines = [
        f"### {row['title']}",
        "",
        row["description"],
        "",
        f"Action id `{row['id']}` · {kind} · API: {calls}",
        "",
        "Inputs: " + (", ".join(inputs) if inputs else "none") + ".",
        "",
    ]
    if row["area"] == "Everyday":
        outputs = ", ".join(
            f"`{o['name']}`"
            for o in row["outputs"]
            if o["name"] not in {"external_effect_status", "definitely_no_external_effect"}
        )
        lines += ["Results: " + outputs + ".", ""]
    return "\n".join(lines)


def api_pages(rows: list[dict[str, Any]]) -> dict[str, dict[str, Any]]:
    pages: dict[str, dict[str, Any]] = {}
    total = len(rows)
    counts = {area: sum(1 for r in rows if r["area"] == area) for area in PAGE_IDS}
    overview = "\n".join(
        [
            f"The steps call the Jotform API of the connected account: {total} steps in all, "
            "the everyday ones first.",
            "",
            "- **Results.** A generated step returns `status`, `data` (the `content` Jotform "
            "returned), `limit_left` (the API calls left today) and `warnings`; a list also "
            "`result_set`.",
            "- **Inputs as documented.** Form fields written `prefix[...]` in the documentation "
            'are one object input: `{"1": "Hello"}` under `submission` is sent as '
            "`submission[1]=Hello`. JSON parameters are sent as the JSON body.",
            "- **Confirmed changes.** Jotform confirms a change inside its answer "
            "(`responseCode` 200). An answer without it leaves the change unknown: the step "
            "says so, and you check Jotform before running it again.",
            "- **Changes are sent once.** A step that changes data is never retried "
            "automatically. Test runs never send changes.",
            "- **Daily calls.** Jotform counts the API calls of a key per day by plan; every "
            "step returns what is left.",
            "",
            "The steps by area:",
            "",
            *[f"- **{area}** ({counts[area]} steps)" for area in PAGE_IDS],
        ]
    )
    everyday = "\n".join(step_text(r) for r in rows if r["area"] == "Everyday")
    pages["ui/pages/jotform-api.yaml"] = {
        "page_id": "jotform-api",
        "title": "API steps",
        "description": "How the steps work, and the everyday steps.",
        "components": [
            {
                "component_id": "api_overview",
                "type": "markdown",
                "title": "How the steps work",
                "body": overview + "\n",
            },
            {
                "component_id": "steps_everyday",
                "type": "markdown",
                "title": "Everyday",
                "body": everyday,
            },
        ],
    }
    for area, page_id in PAGE_IDS.items():
        area_rows = [r for r in rows if r["area"] == area]
        pages[f"ui/pages/{page_id}.yaml"] = {
            "page_id": page_id,
            "title": f"API steps: {area}",
            "description": f"The {len(area_rows)} steps for {area.lower()}.",
            "components": [
                {
                    "component_id": "steps_" + snake(area),
                    "type": "markdown",
                    "title": area,
                    "body": "\n".join(step_text(r) for r in area_rows),
                }
            ],
        }
    return pages


def coverage_page(registry: dict[str, Any], data: dict[str, Any]) -> dict[str, Any]:
    ops = list(registry["operations"].values())
    source = registry["source"]
    total = len(ops)
    reads = sum(1 for e in ops if e["kind"] == "read")
    documented = len(data["operations"])
    left_out = [
        f"- `{m} {p}`: {names.EXCLUDED[(m, p)].split(':')[0].split(' (')[0]}."
        for m, p in names.EXCLUDED
    ]
    body = "\n".join(
        [
            f"The Jotform API documentation ({source['page']}) loads its list of operations "
            f"from a script (downloaded {source['downloaded']}, SHA-256 "
            f"`{source['sha256'][:12]}…`). It lists {documented} operations; **{total} of them "
            "have their own step**.",
            "",
            f"- **{reads} reads** and **{total - reads} changes**. Every change is an external "
            "effect for Flow Steward, so test runs never send it.",
            "- Left out:",
            *[f"  {line}" for line in left_out],
            "",
            "The everyday steps on top: test the connection, check readiness, build a support "
            "report, list forms, describe a form's questions, read new submissions since a "
            "moment, read one submission, create a submission, download an uploaded file, and "
            "list, add and remove webhooks.",
        ]
    )
    return {
        "page_id": "coverage",
        "title": "Coverage",
        "description": "What of the documented Jotform API the steps offer.",
        "components": [
            {
                "component_id": "coverage_summary",
                "type": "markdown",
                "title": "Coverage",
                "body": body + "\n",
            }
        ],
    }


# -- output --------------------------------------------------------------------------------


def outputs() -> dict[str, Any]:
    data = facts()
    ids = step_ids()
    missing = [key(op) for op in operations(data) if key(op) not in ids]
    if missing:
        raise SystemExit(f"no step id for {missing[:5]}; run with --new-ids")
    registry = build_registry(data, ids)
    rows = manifest_rows(registry)
    out: dict[str, Any] = {
        "runtime/registry.json": registry,
        "contracts/operation_manifest.yaml": operation_manifest(rows),
        "contracts/step_ui_manifest.yaml": step_ui_manifest(rows),
        "contracts/artifact_policies.yaml": artifact_policies(rows),
        "contracts/connection_types.yaml": connection_types(),
        "ui/actions/actions.yaml": actions_manifest(rows),
        "ui/pages/coverage.yaml": coverage_page(registry, data),
        "extension.yaml": extension_yaml(rows, registry),
    }
    out.update(api_pages(rows))
    return out


class _Dumper(yaml.SafeDumper):
    pass


def _str(dumper: yaml.SafeDumper, value: str) -> Any:
    style = "|" if "\n" in value else None
    return dumper.represent_scalar("tag:yaml.org,2002:str", value, style=style)


_Dumper.add_representer(str, _str)


def render(path: str, value: Any) -> str:
    if path.endswith(".json"):
        return json.dumps(value, ensure_ascii=False, indent=1, sort_keys=True) + "\n"
    if path == "extension.yaml":
        # The form `flow-steward extensions lock-deps` writes, so it changes nothing.
        return yaml.safe_dump(value, sort_keys=False)
    return HEADER + yaml.dump(value, Dumper=_Dumper, sort_keys=False, allow_unicode=True, width=100)


def main(argv: list[str]) -> int:
    if "--new-ids" in argv:
        data = facts()
        ids = step_ids()
        used = set(ids.values()) | {c["operation_id"] for c in composite_specs.COMPOSITES}
        for op in operations(data):
            if key(op) not in ids:
                sid = new_step_id(names.TITLES[(op["method"], op["path"])])
                if sid in used:
                    raise SystemExit(f"step id {sid} is taken")
                ids[key(op)] = sid
                used.add(sid)
        STEP_IDS.write_text(json.dumps(ids, indent=1, sort_keys=True) + "\n", encoding="utf-8")
    generated = outputs()
    for path, value in generated.items():
        target = BUNDLE / path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(render(path, value), encoding="utf-8")
    print("generated", len(generated), "files")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
